1	'use client';
2	
3	import React, { useState, useEffect, useRef, useCallback } from 'react';
4	import { useActiveJobs, type ActiveJob, type CompletedJob } from '../hooks/useActiveJobs';
5	import { useLayoutMode } from '@interface/contexts/layout-mode-context';
6	import { useDesktopMode } from '@interface/contexts/desktop-mode-context';
7	import { useUI } from '@interface/contexts/ui-context';
8	import { useTaskFeedback } from '../hooks/useTaskFeedback';
9	
10	const GOHUFONT_FONT_FACE = `
11	@font-face {
12	  font-family: 'Gohufont';
13	  src: url('/fonts/Gohu/GohuFontuni14NerdFontMono-Regular.ttf') format('truetype');
14	  font-weight: normal;
15	  font-style: normal;
16	  font-display: swap;
17	}
18	`;
19	
20	const ensureGohufont = () => {
21	  if (typeof document === 'undefined') return;
22	  if (document.getElementById('gohufont-active-jobs')) return;
23	  const style = document.createElement('style');
24	  style.id = 'gohufont-active-jobs';
25	  style.textContent = GOHUFONT_FONT_FACE;
26	  document.head.appendChild(style);
27	};
28	
29	function formatElapsed(ms: number): string {
30	  const seconds = Math.floor(ms / 1000);
31	  if (seconds < 60) return `${seconds}s`;
32	  const minutes = Math.floor(seconds / 60);
33	  if (minutes < 60) return `${minutes}m ${seconds % 60}s`;
34	  const hours = Math.floor(minutes / 60);
35	  return `${hours}h ${minutes % 60}m`;
36	}
37	
38	/** Friendly display name for an ACP-style agent kind */
39	function acpKindDisplay(kind: string): string {
40	  switch (kind) {
41	    case 'claude-code': return 'Claude Code';
42	    case 'codex': return 'Codex';
43	    case 'gemma': return 'Gemma';
44	    case 'qwen': return 'Qwen';
45	    default: return kind.replace(/-/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
46	  }
47	}
48	
49	/** Strip a key like agent:claude-code:<uuid> down to just the id */
50	function stripAgentKey(raw: string, kind: string): string {
51	  return raw
52	    .replace(new RegExp(`^agent:${kind}:`), '')
53	    .replace(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/, 'Coding session');
54	}
55	
56	const ACP_KINDS = new Set(['claude-code', 'codex', 'gemma', 'qwen']);
57	
58	/** Shape returned by /api/tasks */
59	interface PolledTask {
60	  taskId: string;
61	  title: string;
62	  description?: string;
63	  status: 'pending' | 'running' | 'complete' | 'failed';
64	  screenshotUrl?: string | null;
65	  approvalStatus?: string;
66	  createdAt?: string;
67	  updatedAt?: string;
68	}
69	
70	/** Returns true if a string looks like a raw hex ID / UUID / hash rather than a human name */
71	function looksLikeHexId(s: string): boolean {
72	  // Strip dashes, spaces, dots, and ellipsis — UUIDs can arrive formatted many ways
73	  const stripped = s.replace(/[-\s.…]+/g, '');
74	  return /^[0-9a-f]{6,}$/i.test(stripped);
75	}
76	
77	/** Shared name lookup for subagent tasks */
78	const SUBAGENT_NAMES: Record<string, string> = {
79	  'active-jobs-descriptions': 'Making task names human-friendly',
80	  'active-jobs-widget': 'Building jobs dashboard',
81	  'widget-test': 'Testing widget components',
82	  'pipeline-timing': 'Analyzing voice latency',
83	  'fix-fast-voice': 'Fixing voice pipeline',
84	  'fix-duplicate-messages': 'Fixing duplicate messages',
85	  'fix-simple-silence': 'Fixing voice silence',
86	  'fix-canvas-leak': 'Fixing canvas memory leak',
87	  'canvas-zindex': 'Fixing avatar visibility',
88	  'context-audit': 'Optimizing response speed',
89	  'swarm-architecture': 'Designing multi-agent system',
90	  'regression-analysis': 'Running regression analysis',
91	  'investigate-duplicates': 'Investigating duplicate events',
92	  'mobile-widget-fix': 'Fixing mobile layout',
93	  'tasklist-ui': 'Redesigning task list',
94	  'pearlos-bridge-rewrite': 'Rewriting PearlOS event bridge',
95	  'desktop-icon-overhaul': 'Redesigning desktop icons',
96	  'home-desktop-toggle': 'Building home/desktop toggle',
97	  'desktop-nav-buttons': 'Adding desktop navigation button...

