1	'use client';
2	
3	import { useState, useEffect, useCallback } from 'react';
4	
5	export interface ActiveJob {
6	  id: string;
7	  key: string;
8	  label: string;
9	  description: string;
10	  status: 'running' | 'complete' | 'idle' | 'failed';
11	  channel: string;
12	  model: string;
13	  startedAt: number;
14	  updatedAt: number;
15	  elapsedMs: number;
16	  spawnedBy: string;
17	  displayName: string;
18	  totalTokens: number;
19	  kind: string;
20	  agents: string[];
21	  fadingOut?: boolean;
22	}
23	
24	export interface CompletedJob extends Omit<ActiveJob, 'status' | 'fadingOut'> {
25	  status: 'complete';
26	  completedAt: number;
27	}
28	
29	const POLL_INTERVAL = 5000;
30	const MAX_COMPLETED_HISTORY = 25;
31	
32	/**
33	 * Internal/system jobs that shouldn't appear in the user-facing widget.
34	 * These are OpenClaw cron heartbeats, scheduled checks, and other
35	 * infrastructure tasks that would confuse end users.
36	 */
37	const INTERNAL_JOB_PATTERNS = [
38	  /heartbeat/i,
39	  /scheduled.?check/i,
40	  /health.?check/i,
41	  /healthcheck/i,
42	  /health.?monitor/i,
43	  /discord.?progress/i,
44	  /progress.?update/i,
45	  /sync.?protocol/i,
46	  /memory.?maintenance/i,
47	  /activity.?log/i,
48	  /cron.?run/i,
49	  /inbox.?check/i,
50	  /email.?check/i,
51	  /calendar.?check/i,
52	  /weather.?check/i,
53	];
54	
55	function isInternalSystemJob(job: ActiveJob): boolean {
56	  // All cron jobs are internal system tasks — users don't need to see scheduled checks
57	  if (job.kind === 'cron') return true;
58	
59	  // Check label and description against known internal patterns
60	  const text = `${job.label} ${job.displayName} ${job.description}`.toLowerCase();
61	  return INTERNAL_JOB_PATTERNS.some((pattern) => pattern.test(text));
62	}
63	
64	export function useActiveJobs() {
65	  const [jobs, setJobs] = useState<ActiveJob[]>([]);
66	  const [completedHistory, setCompletedHistory] = useState<CompletedJob[]>([]);
67	  const [error, setError] = useState<string | null>(null);
68	
69	  // Dismiss a job from the active list (called after user confirms via thumbs up/down)
70	  const dismissJob = useCallback((jobId: string) => {
71	    setJobs((cur) => cur.filter((c) => c.id !== jobId));
72	  }, []);
73	
74	  const fetchJobs = useCallback(async () => {
75	    try {
76	      const res = await fetch('/api/openclaw/sessions');
77	      if (!res.ok) {
78	        setError('Failed to fetch');
79	        return;
80	      }
81	      const data = await res.json();
82	      setError(null);
83	
84	      // Filter out internal system jobs that shouldn't be user-facing
85	      const incoming: ActiveJob[] = (Array.isArray(data.jobs) ? data.jobs : []).filter(
86	        (job: ActiveJob) => !isInternalSystemJob(job)
87	      );
88	
89	      setJobs((prev) => {
90	        const map = new Map<string, ActiveJob>();
91	
92	        // Keep previously completed jobs that haven't been dismissed
93	        for (const j of prev) {
94	          if (j.status === 'complete') map.set(j.id, j);
95	        }
96	
97	        // Update with incoming
98	        for (const j of incoming) {
99	          const existing = prev.find((p) => p.id === j.id);
100	          const wasRunning = existing?.status === 'running';
101	          const nowComplete = j.status === 'complete';
102	
103	          if (nowComplete && wasRunning) {
104	            // Job just completed — mark it but keep it visible (no auto-removal)
105	            map.set(j.id, { ...j, fadingOut: false });
106	            
107	            // Add to completed history for reference
108	            setCompletedHistory((history) => {
109	              const completedJob: CompletedJob = {
110	                ...j,
111	                status: 'complete',
112	                completedAt: Date.now(),
113	              };
114	              const filtered = history.filter((h) => h.id !== j.id);
115	              return [completedJob, ...filtered].slice(0, MAX_COMPLETED_HISTORY);
116	            });
117	   ...

