17	}
18	
19	/**
20	 * Extract a two-sentence description from the session JSONL content.
21	 * Looks for the first user message and generates a readable summary.
22	 */
23	function extractDescription(content: string, label?: string): string | undefined {
24	  try {
25	    const lines = content.split("\n");
26	    
27	    // Find the first user message (contains the task instructions)
28	    for (const line of lines) {
29	      if (!line.trim()) continue;
30	      try {
31	        const entry = JSON.parse(line);
32	        if (entry.type === "message" && entry.message?.role === "user") {
33	          const text = typeof entry.message.content === "string"
34	            ? entry.message.content
35	            : Array.isArray(entry.message.content)
36	              ? entry.message.content
37	                  .filter((c: { type: string }) => c.type === "text")
38	                  .map((c: { text: string }) => c.text)
39	                  .join(" ")
40	              : "";
41	          
42	          if (!text) continue;
43	          
44	          return generateTwoSentenceSummary(text, label);
45	        }
46	      } catch {
47	        continue;
48	      }
49	    }
50	  } catch {
51	    // Ignore extraction errors
52	  }
53	  return undefined;
54	}
55	
56	/**
57	 * Generate a clean two-sentence summary from task instructions.
58	 * First sentence: What the agent is doing.
59	 * Second sentence: What it's investigating or building.
60	 */
61	function generateTwoSentenceSummary(taskText: string, label?: string): string {
