73	    ? label.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase())
74	    : null;
75	
76	  // Look for problem/requirement patterns
77	  const problemMatch = cleaned.match(/(?:Problem:|Issue:|Bug:|Fix:)\s*([^.!?]+[.!?]?)/i);
78	  const requirementMatch = cleaned.match(/(?:Requirement|Goal|Task|Implement|Build|Create|Add|Update|Fix)[\s:]+([^.!?]+[.!?]?)/i);
79	  const investigateMatch = cleaned.match(/(?:Investigat|Check|Debug|Analyz|Review|Audit)[\w]*[\s:]+([^.!?]+[.!?]?)/i);
80	
81	  // Build first sentence (what the agent is doing)
82	  let sentence1: string;
83	  if (actionLabel) {
84	    sentence1 = `Working on ${actionLabel.toLowerCase()}.`;
85	  } else if (requirementMatch) {
86	    const action = requirementMatch[1].trim().replace(/[.!?]$/, "");
87	    sentence1 = `${action.charAt(0).toUpperCase() + action.slice(1)}.`;
